     1→// Package settings provides configuration loading for Entire.
     2→// This package is separate from cli to allow strategy package to import it
     3→// without creating an import cycle (cli imports strategy).
     4→package settings
     5→
     6→import (
     7→	"bytes"
     8→	"encoding/json"
     9→	"fmt"
    10→	"os"
    11→
    12→	"github.com/entireio/cli/cmd/entire/cli/paths"
    13→)
    14→
    15→// DefaultStrategyName is the default strategy when none is configured.
    16→// This is duplicated here to avoid importing the strategy package (which would create a cycle).
    17→const DefaultStrategyName = "manual-commit"
    18→
    19→const (
    20→	// EntireSettingsFile is the path to the Entire settings file
    21→	EntireSettingsFile = ".entire/settings.json"
    22→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
    23→	EntireSettingsLocalFile = ".entire/settings.local.json"
    24→)
    25→
    26→// EntireSettings represents the .entire/settings.json configuration
    27→type EntireSettings struct {
    28→	// Strategy is the name of the git strategy to use
    29→	Strategy string `json:"strategy"`
    30→
    31→	// Enabled indicates whether Entire is active. When false, CLI commands
    32→	// show a disabled message and hooks exit silently. Defaults to true.
    33→	Enabled bool `json:"enabled"`
    34→
    35→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
    36→	// This is used for development when the binary is not installed
    37→	LocalDev bool `json:"local_dev,omitempty"`
    38→
    39→	// LogLevel sets the logging verbosity (debug, info, warn, error).
    40→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
    41→	// Defaults to "info".
    42→	LogLevel string `json:"log_level,omitempty"`
    43→
    44→	// StrategyOptions contains strategy-specific configuration
    45→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
    46→
    47→	// Telemetry controls anonymous usage analytics.
    48→	// nil = not asked yet (show prompt), true = opted in, false = opted out
    49→	Telemetry *bool `json:"telemetry,omitempty"`
    50→}
    51→
    52→// Load loads the Entire settings from .entire/settings.json,
    53→// then applies any overrides from .entire/settings.local.json if it exists.
    54→// Returns default settings if neither file exists.
    55→// Works correctly from any subdirectory within the repository.
    56→func Load() (*EntireSettings, error) {
    57→	// Get absolute paths for settings files
    58→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
    59→	if err != nil {
    60→		settingsFileAbs = EntireSettingsFile // Fallback to relative
    61→	}
    62→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
    63→	if err != nil {
    64→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
    65→	}
    66→
    67→	// Load base settings
    68→	settings, err := loadFromFile(settingsFileAbs)
    69→	if err != nil {
    70→		return nil, fmt.Errorf("reading settings file: %w", err)
    71→	}
    72→
    73→	// Apply local overrides if they exist
    74→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
    75→	if err != nil {
    76→		if !os.IsNotExist(err) {
    77→			return nil, fmt.Errorf("reading local settings file: %w", err)
    78→		}
    79→		// Local file doesn't exist, continue without overrides
    80→	} else {
    81→		if err := mergeJSON(settings, localData); err != nil {
    82→			return nil, fmt.Errorf("merging local settings: %w", err)
    83→		}
    84→	}
    85→
    86→	applyDefaults(settings)
    87→
    88→	return settings, nil
    89→}
    90→
    91→// loadFromFile loads settings from a specific file path.
    92→// Returns default settings if the file doesn't exist.
    93→func loadFromFile(filePath string) (*EntireSettings, error) {
    94→	settings := &EntireSettings{
    95→		Strategy: DefaultStrategyName,
    96→		Enabled:  true, // Default to enabled
    97→	}
    98→
    99→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
   100→	if err != nil {
   101→		if os.IsNotExist(err) {
   102→			return settings, nil
   103→		}
   104→		return nil, fmt.Errorf("%w", err)
   105→	}
   106→
   107→	dec := json.NewDecoder(bytes.NewReader(data))
   108→	dec.DisallowUnknownFields()
   109→	if err := dec.Decode(settings); err != nil {
   110→		return nil, fmt.Errorf("parsing settings file: %w", err)
   111→	}
   112→	applyDefaults(settings)
   113→
   114→	return settings, nil
   115→}
   116→
   117→// mergeJSON merges JSON data into existing settings.
   118→// Only non-zero values from the JSON override existing settings.
   119→func mergeJSON(settings *EntireSettings, data []byte) error {
   120→	// First, validate that there are no unknown keys using strict decoding
   121→	dec := json.NewDecoder(bytes.NewReader(data))
   122→	dec.DisallowUnknownFields()
   123→	var temp EntireSettings
   124→	if err := dec.Decode(&temp); err != nil {
   125→		return fmt.Errorf("parsing JSON: %w", err)
   126→	}
   127→
   128→	// Parse into a map to check which fields are present
   129→	var raw map[string]json.RawMessage
   130→	if err := json.Unmarshal(data, &raw); err != nil {
   131→		return fmt.Errorf("parsing JSON: %w", err)
   132→	}
   133→
   134→	// Override strategy if present and non-empty
   135→	if strategyRaw, ok := raw["strategy"]; ok {
   136→		var s string
   137→		if err := json.Unmarshal(strategyRaw, &s); err != nil {
   138→			return fmt.Errorf("parsing strategy field: %w", err)
   139→		}
   140→		if s != "" {
   141→			settings.Strategy = s
   142→		}
   143→	}
   144→
   145→	// Override enabled if present
   146→	if enabledRaw, ok := raw["enabled"]; ok {
   147→		var e bool
   148→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
   149→			return fmt.Errorf("parsing enabled field: %w", err)
   150→		}
   151→		settings.Enabled = e
   152→	}
   153→
   154→	// Override local_dev if present
   155→	if localDevRaw, ok := raw["local_dev"]; ok {
   156→		var ld bool
   157→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
   158→			return fmt.Errorf("parsing local_dev field: %w", err)
   159→		}
   160→		settings.LocalDev = ld
   161→	}
   162→
   163→	// Override log_level if present and non-empty
   164→	if logLevelRaw, ok := raw["log_level"]; ok {
   165→		var ll string
   166→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
   167→			return fmt.Errorf("parsing log_level field: %w", err)
   168→		}
   169→		if ll != "" {
   170→			settings.LogLevel = ll
   171→		}
   172→	}
   173→
   174→	// Merge strategy_options if present
   175→	if optionsRaw, ok := raw["strategy_options"]; ok {
   176→		var opts map[string]any
   177→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
   178→			return fmt.Errorf("parsing strategy_options field: %w", err)
   179→		}
   180→		if settings.StrategyOptions == nil {
   181→			settings.StrategyOptions = opts
   182→		} else {
   183→			for k, v := range opts {
   184→				settings.StrategyOptions[k] = v
   185→			}
   186→		}
   187→	}
   188→
   189→	// Override telemetry if present
   190→	if telemetryRaw, ok := raw["telemetry"]; ok {
   191→		var t bool
   192→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
   193→			return fmt.Errorf("parsing telemetry field: %w", err)
   194→		}
   195→		settings.Telemetry = &t
   196→	}
   197→
   198→	return nil
   199→}
   200→
   201→func applyDefaults(settings *EntireSettings) {
   202→	if settings.Strategy == "" {
   203→		settings.Strategy = DefaultStrategyName
   204→	}
   205→}
   206→
   207→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
   208→// Returns false by default if settings cannot be loaded or the key is missing.
   209→func IsSummarizeEnabled() bool {
   210→	settings, err := Load()
   211→	if err != nil {
   212→		return false
   213→	}
   214→	return settings.IsSummarizeEnabled()
   215→}
   216→
   217→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
   218→func (s *EntireSettings) IsSummarizeEnabled() bool {
   219→	if s.StrategyOptions == nil {
   220→		return false
   221→	}
   222→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
   223→	if !ok {
   224→		return false
   225→	}
   226→	enabled, ok := summarizeOpts["enabled"].(bool)
   227→	if !ok {
   228→		return false
   229→	}
   230→	return enabled
   231→}
   232→
   233→// IsMultiSessionWarningDisabled checks if multi-session warnings are disabled.
   234→// Returns false (show warnings) by default if the key is missing.
   235→func (s *EntireSettings) IsMultiSessionWarningDisabled() bool {
   236→	if s.StrategyOptions == nil {
   237→		return false
   238→	}
   239→	if disabled, ok := s.StrategyOptions["disable_multisession_warning"].(bool); ok {
   240→		return disabled
   241→	}
   242→	return false
   243→}
