    60→func LoadEntireSettings() (*EntireSettings, error) {
    61→	// Get absolute paths for settings files
    62→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
    63→	if err != nil {
    64→		settingsFileAbs = EntireSettingsFile // Fallback to relative
    65→	}
    66→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
    67→	if err != nil {
    68→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
    69→	}
