   189→// loadSettingsFromFile loads settings from a specific file path.
   190→// Returns default settings if the file doesn't exist.
   191→func loadSettingsFromFile(filePath string) (*EntireSettings, error) {
   192→	settings := &EntireSettings{
   193→		Strategy: strategy.DefaultStrategyName,
   194→		Enabled:  true, // Default to enabled
   195→	}
   196→
   197→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
   198→	if err != nil {
   199→		if os.IsNotExist(err) {
   200→			return settings, nil
   201→		}
   202→		return nil, fmt.Errorf("%w", err)
   203→	}
   204→
   205→	dec := json.NewDecoder(bytes.NewReader(data))
   206→	dec.DisallowUnknownFields()
   207→	if err := dec.Decode(settings); err != nil {
   208→		return nil, fmt.Errorf("parsing settings file: %w", err)
