   222→func saveSettingsToFile(settings *EntireSettings, filePath string) error {
   223→	// Get absolute path for the file
   224→	filePathAbs, err := paths.AbsPath(filePath)
   225→	if err != nil {
   226→		filePathAbs = filePath // Fallback to relative
   227→	}
   228→
   229→	// Ensure directory exists
   230→	dir := filepath.Dir(filePathAbs)
   231→	if err := os.MkdirAll(dir, 0o750); err != nil {
   232→		return fmt.Errorf("creating settings directory: %w", err)
   233→	}
   234→
   235→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
   236→	if err != nil {
   237→		return fmt.Errorf("marshaling settings: %w", err)
   238→	}
   239→
   240→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
   241→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
   242→		return fmt.Errorf("writing settings file: %w", err)
   243→	}
   244→	return nil
   245→}
