   257→// GetStrategy returns the configured strategy instance.
   258→// Falls back to default if the configured strategy is not found.
   259→//
   260→//nolint:ireturn // Factory pattern requires returning the interface
   261→func GetStrategy() strategy.Strategy {
   262→	settings, err := LoadEntireSettings()
   263→	if err != nil {
   264→		// Fall back to default on error
   265→		logging.Info(context.Background(), "falling back to default strategy - failed to load settings",
   266→			slog.String("error", err.Error()))
   267→		return strategy.Default()
   268→	}
   269→
   270→	s, err := strategy.Get(settings.Strategy)
   271→	if err != nil {
   272→		// Fall back to default if strategy not found
   273→		logging.Info(context.Background(), "falling back to default strategy - configured strategy not found",
   274→			slog.String("configured", settings.Strategy),
   275→			slog.String("error", err.Error()))
   276→		return strategy.Default()
   277→	}
   278→
   279→	return s
   280→}
