   309→// GetAgentsWithHooksInstalled returns names of agents that have hooks installed.
   310→func GetAgentsWithHooksInstalled() []agent.AgentName {
   311→	var installed []agent.AgentName
   312→	for _, name := range agent.List() {
   313→		ag, err := agent.Get(name)
   314→		if err != nil {
   315→			continue
   316→		}
   317→		if hs, ok := ag.(agent.HookSupport); ok && hs.AreHooksInstalled() {
   318→			installed = append(installed, name)
   319→		}
   320→	}
   321→	return installed
   322→}
