   324→// JoinAgentNames joins agent names into a comma-separated string.
   325→func JoinAgentNames(names []agent.AgentName) string {
   326→	strs := make([]string, len(names))
   327→	for i, n := range names {
   328→		strs[i] = string(n)
   329→	}
   330→	return strings.Join(strs, ",")
   331→}
