   280→// checkConcurrentSessions checks for concurrent session conflicts and shows warnings if needed.
   281→// Returns a non-nil error if the hook should be skipped due to an unresolved conflict or if a check fails; otherwise returns nil.
   282→func checkConcurrentSessions(ag agent.Agent, sessionID string) error {
   283→	strat := GetStrategy()
   284→
   285→	concurrentChecker, ok := strat.(strategy.ConcurrentSessionChecker)
   286→	if !ok {
   287→		return nil // Strategy doesn't support concurrent checks
   288→	}
   289→
   290→	// Check for other active sessions with checkpoints (on current HEAD)
   291→	existingSessionState, checkErr := concurrentChecker.HasOtherActiveSessionsWithCheckpoints(sessionID)
   292→	hasConflict := checkErr == nil && existingSessionState != nil
   293→
   294→	if hasConflict {
   295→		// Try to get the conflicting session's agent type from its state file
   296→		// If it's a different agent type, use that agent's resume command format
   297→		var resumeCmd string
   298→		if existingSessionState != nil && existingSessionState.AgentType != "" {
   299→			if conflictingAgent, agentErr := agent.GetByAgentType(existingSessionState.AgentType); agentErr == nil {
   300→				resumeCmd = conflictingAgent.FormatResumeCommand(existingSessionState.SessionID)
   301→			}
   302→		}
   303→		// Fall back to current agent if we couldn't get the conflicting agent
   304→		if resumeCmd == "" {
   305→			resumeCmd = ag.FormatResumeCommand(existingSessionState.SessionID)
   306→		}
   307→
   308→		// Get CLI command name for fresh start (e.g., "claude" or "gemini")
   309→		cliCmd := "claude"
   310→		if ag.Type() == agent.AgentTypeGemini {
   311→			cliCmd = "gemini"
   312→		}
   313→
   314→		message := fmt.Sprintf(
   315→			"\nYou have an existing session running (%s).\n"+
   316→				"Do you want to continue with this new session (%s)?\n\n"+
   317→				"Yes: Ignore this warning\n"+
   318→				"No: Type /exit, then either:\n"+
   319→				"  • Resume the other session: %s\n"+
   320→				"  • Reset and start fresh: entire reset --force && %s\n\n"+
   321→				"To hide this notice in the future: entire enable --disable-multisession-warning",
   322→			existingSessionState.SessionID,
   323→			sessionID,
   324→			resumeCmd,
   325→			cliCmd,
   326→		)
   327→		// Output warning JSON response using agent-specific format
   328→		if err := outputConflictWarning(ag, message); err != nil {
   329→			return err
   330→		}
   331→	}
   332→
   333→	return nil
   334→}
   335→
   336→// outputConflictWarning outputs a conflict warning message using the appropriate format for the agent.
   337→func outputConflictWarning(ag agent.Agent, message string) error {
   338→	//nolint:exhaustive // default case handles all other agent types
   339→	switch ag.Type() {
   340→	case agent.AgentTypeGemini:
   341→		return outputGeminiWarningResponse(message)
   342→	default:
   343→		return outputHookResponse(message)
   344→	}
   345→}
   346→
   347→// geminiWarningResponse represents a JSON response for Gemini CLI session-start warnings.
   348→// Unlike blocking responses, this just injects a system message without blocking the session.
   349→type geminiWarningResponse struct {
   350→	SystemMessage string `json:"systemMessage,omitempty"`
   351→}
   352→
   353→// outputGeminiWarningResponse outputs a warning JSON response to stdout for Gemini CLI hooks.
   354→// This injects a system message into the conversation without blocking the session.
   355→func outputGeminiWarningResponse(message string) error {
   356→	resp := geminiWarningResponse{
   357→		SystemMessage: message,
   358→	}
   359→	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
   360→		return fmt.Errorf("failed to encode gemini warning response: %w", err)
   361→	}
   362→	return nil
   363→}
